"""Candidate elbow_limits.h from the MJ11 whole-arm tier tables, in the exact format of firmware/gen_tables.py (EL_N1, EL_N2, EL_S1, EL_S2, EL_F, EL_R; look-up = MIN of the 4 surrounding nodes).
Written to stl/j1r2_sweep/firmware_candidate/ only: the firmware headers live in the claude.ai Project, and control.h still assumes the pre-J1' S1/S2 axes (axis S1 -> S1p here), so this is a CANDIDATE, not a drop-in.
usage: J1R2_ROOT=<work root> python3 mj11_gen_elbow_h.py (after mj11_tables.py)"""
import os, sys, json, hashlib
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import clib as L
R = os.path.join(L.ROOT, "stl", "j1r2_sweep"); ax = json.load(open(os.path.join(R, "mj11_sweep_axes.json"))); s1, s2 = ax["S1"], ax["S2"]
el = json.load(open(os.path.join(R, "mj11_elbow_limits_full.json"))); elr = json.load(open(os.path.join(R, "mj11_elbow_limits_restricted.json"))); key = lambda a, b: f"{a:.0f},{b:.0f}"
os.makedirs(os.path.join(R, "firmware_candidate"), exist_ok=True)
with open(os.path.join(R, "firmware_candidate", "elbow_limits.h"), "w") as f:
    f.write("// CANDIDATE generated by cad/j1r2/mj11_gen_elbow_h.py (format of firmware/gen_tables.py) from stl/j1r2_sweep/mj11_elbow_limits_full.json / _restricted.json -- do not edit\n"
            "// MJ11 whole-arm sweep (2026-11-03), source sha256 %s.  Axis 1 is S1' (not the old S1).  Largest sampled elbow angle (20 deg steps) with every sampled E' <= E contact-free at the project gates\n"
            "// (3 mm parts, 2 mm skin, 60 mm head/neck) for every sampled S3 / W1 / W2 / W3 of the tier.  EL_F: any S3 / wrist.  EL_R: S3 0, W2 0, W3 0 (grid-resolved |S3|<=30, |W2|<=30, |W3|<=15), W1 any.\n"
            "// -1 = not allowed in that tier (use the NEUTRAL tier, see control.h).  Look-up = MIN of the 4 surrounding grid points.\n#pragma once\n" % hashlib.sha256(open(os.path.join(R, "mj11_elbow_limits_full.json"), "rb").read()).hexdigest()[:16])
    f.write(f"const int EL_N1 = {len(s1)}, EL_N2 = {len(s2)};\nconst float EL_S1[EL_N1] = {{{','.join(f'{v:.2f}f' for v in s1)}}};\nconst float EL_S2[EL_N2] = {{{','.join(f'{v:.2f}f' for v in s2)}}};\n")
    for nm, tab in (("EL_F", el), ("EL_R", elr)):
        f.write(f"const float {nm}[EL_N1][EL_N2] = {{\n" + ",\n".join("{" + ",".join(f"{tab[key(a, b)]:.1f}f" for b in s2) + "}" for a in s1) + "};\n")
print("written", len(s1), len(s2))
